@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_element">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    [Parameter] public int TimeoutSeconds { get; set; } = 300;

    [Parameter] public EventCallback OnIdle { get; set; }

    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _element;
    private IJSObjectReference? _module;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/UserActivityTracker.razor.js");
            await _module.InvokeVoidAsync("init", _element, _dotNetRef, TimeoutSeconds * 1000);
        }
    }

    [JSInvokable]
    public async Task NotifyIdle()
    {
        await OnIdle.InvokeAsync();
    }

    [JSInvokable]
    public async Task NotifyActive()
    {
        await OnActive.InvokeAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            try
            {
                await _module.InvokeVoidAsync("dispose");
                await _module.DisposeAsync();
            }
            catch (JSDisconnectedException)
            {
                // Circuit already gone — nothing to clean up on the client.
            }
        }
        _dotNetRef?.Dispose();
    }
}

let timer = null;
let dotNetRef = null;
let isIdle = false;
let timeoutMs = 0;
let element = null;

const events = ["mousemove", "keydown", "click", "scroll"];

function onActivity() {
    if (isIdle) {
        isIdle = false;
        dotNetRef.invokeMethodAsync("NotifyActive");
    }
    resetTimer();
}

function resetTimer() {
    clearTimeout(timer);
    timer = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("NotifyIdle");
    }, timeoutMs);
}

export function init(el, ref, timeout) {
    element = el;
    dotNetRef = ref;
    timeoutMs = timeout;
    isIdle = false;

    events.forEach(e => element.addEventListener(e, onActivity, { passive: true }));
    resetTimer();
}

export function dispose() {
    clearTimeout(timer);
    if (element) {
        events.forEach(e => element.removeEventListener(e, onActivity));
    }
    timer = null;
    dotNetRef = null;
    element = null;
    isIdle = false;
}

